window.MG_LAZY_DATA["data/lazy/resources/hpc-v27-068-f140670d635d5d89.json"]={sha256:"f140670d635d5d898c4776722b99d322d7b47c4b3a97f34c841d5610e4340add",value:{"sources":[{"id":"v27-case-7f1ea44aa13052c6","url":"https://nek5000.github.io/NekDoc/theory.html","title":"Nek5000 theory","titleEn":"Nek5000 theory","publisher":"Nek5000","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"hpc-v27-068","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"hpc-v27-068","related":[{"id":"hpc-v27-069","referenceUrls":["https://mfem.org/integration/"],"title":"MFEM：Gauss 積分精確度與有限元素混疊","titleEn":"MFEM: Gauss quadrature exactness and finite-element aliasing","why":"用兩課的可觀察驗收條件比較模型邊界：階數增加與精度改善分開證明，固定元素與物理條件。","whyEn":"Compare model boundaries using observable acceptance criteria: Prove increased order and improved accuracy separately under fixed elements and physical conditions.","difference":"使用原創合成資料研究「MFEM：Gauss 積分精確度與有限元素混疊」，從物理或資料契約推導計算，並以反例驗證。完成：交付節點權重表、解析與離散積分、混疊反例及幾何映射檢查。","differenceEn":"Investigate MFEM: Gauss quadrature exactness and finite-element aliasing using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver node-weight tables, analytic and discrete integrals, an aliasing counterexample and a geometry-mapping checklist tied to the actual finite-element integrand.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["將單元素值數乘一百，再對次數九重做；以十除八的三次方核對比例。","分別計兩個節點的四次方與權重，說明規則只保證至三次，因此失敗不是浮點微小誤差。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Multiply the single-element count by one hundred and repeat at degree nine. Independently check the ratio using ten divided by eight, cubed, and keep scalar-value counts distinct from byte counts.","Evaluate the fourth power at both nodes and apply their weights. Explain that the rule guarantees only degree-three exactness, so the observed discrepancy is a structural underintegration error rather than a tiny floating-point artifact.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"hpc-v27-078","referenceUrls":["https://github.com/DrTimothyAldenDavis/SuiteSparse"],"title":"SuiteSparseQR：最小平方殘差與秩虧解辨識","titleEn":"SuiteSparseQR: least-squares residuals and rank-deficient solutions","why":"用兩課的可觀察驗收條件比較模型邊界：階數增加與精度改善分開證明，固定元素與物理條件。","whyEn":"Compare model boundaries using observable acceptance criteria: Prove increased order and improved accuracy separately under fixed elements and physical conditions.","difference":"使用原創合成資料研究「SuiteSparseQR：最小平方殘差與秩虧解辨識」，從物理或資料契約推導計算，並以反例驗證。完成：交付矩陣與殘差、正交性證明、變更觀測結果及相依欄反例。","differenceEn":"Investigate SuiteSparseQR: least-squares residuals and rank-deficient solutions using an original synthetic fixture. Derive the calculation from its physical or data contract, challenge it with a counterexample, and defend a bounded conclusion. Complete: Deliver matrix and residual calculations, orthogonality evidence, changed-observation results and a dependent-column counterexample separating fitted predictions from coefficient uniqueness.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["將單元素值數乘一百，再對次數九重做；以十除八的三次方核對比例。","代入候選解算三列殘差，求二範數；再算兩個欄與殘差的內積，檢查正交。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Multiply the single-element count by one hundred and repeat at degree nine. Independently check the ratio using ten divided by eight, cubed, and keep scalar-value counts distinct from byte counts.","Substitute the proposed solution, compute all three residuals and their Euclidean norm, then take each column dot product with the residual. This independently checks optimality rather than relying on a reported least-squares status.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v27-case-d5b4bc970496056c","url":"https://mfem.org/integration/","title":"MFEM numerical integration","titleEn":"MFEM numerical integration","publisher":"MFEM / Lawrence Livermore National Laboratory","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v27-case-16450ca99b8a2ba6","url":"https://github.com/DrTimothyAldenDavis/SuiteSparse","title":"SuiteSparse official library","titleEn":"SuiteSparse official library","publisher":"Timothy A. Davis / SuiteSparse","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
